import i18n from 'i18next';
import { initReactI18next } from 'react-i18next';
import LanguageDetector from 'i18next-browser-languagedetector';

i18n
  .use(LanguageDetector)
  .use(initReactI18next)
  .init({
    resources: {
      en: {
        translation: {
          app_name: "Agro Zenith",
          detect_btn: "Analyze Crop",
          chat_placeholder: "Ask about fertilizers...",
          soil_btn: "Check Soil Health",
          lang_name: "English"
        }
      },
      ta: {
        translation: {
          app_name: "அக்ரோ ஜெனித்",
          detect_btn: "பயிரை ஆய்வு செய்",
          chat_placeholder: "உரங்களைப் பற்றி கேளுங்கள்...",
          soil_btn: "மண் ஆரோக்கியம்",
          lang_name: "தமிழ்"
        }
      },
      hi: {
        translation: {
          app_name: "एग्रो जेनिथ",
          detect_btn: "फसल की जाँच करें",
          chat_placeholder: "उर्वरकों के बारे में पूछें...",
          soil_btn: "मिट्टी का स्वास्थ्य",
          lang_name: "हिंदी"
        }
      }
    },
    fallbackLng: 'en',
    interpolation: { escapeValue: false }
  });

export default i18n;
